function FSSign(p, g, x, m):
    r <- random in [0, p)
    t <- (r * g) mod p
    c <- H(t, m) mod p
    s <- (r + c*x) mod p
    return (t, s)
function FSVerify(p, g, Y, m, (t, s)):
    c <- H(t, m) mod p
    return (s*g) mod p == (t + c*Y) mod p
